// D05 monoline icons (proposed identity V10): 24 grid, currentColor strokes, offset marigold marker.
// The sprite lives in /assets/identity/v10/icons-d05.svg and is generated by design-system/identity-v10/build.mjs.
export type IconName = 'mic' | 'time' | 'recognition' | 'voice' | 'usefulness' | 'conversations' | 'profile' | 'strategy' | 'writing' | 'design' | 'automation' | 'marketing' | 'advertising' | 'measurement';

export function Icon({name, size = 24, marker = true, className = ''}: {name: IconName; size?: number; marker?: boolean; className?: string}) {
  return (
    <svg className={'icon-d05 ' + className} width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" focusable="false" data-marker={marker ? 'on' : 'off'}>
      <use href={'/assets/identity/v10/icons-d05.svg#' + name} />
    </svg>
  );
}
